WITH null_present AS (
    SELECT EXISTS (SELECT 1 FROM emp WHERE mgr IS NULL) AS has_null
)
SELECT e.empno
FROM emp e, null_present np
WHERE e.job = 'SALES'
  AND NOT np.has_null
  AND NOT EXISTS (
        SELECT 1 FROM emp m WHERE m.mgr = e.empno
    );

WITH no_null_mgr AS (
    SELECT NOT EXISTS (SELECT 1 FROM emp WHERE mgr IS NULL) AS ok
), mgr_set AS (
    SELECT DISTINCT mgr FROM emp WHERE mgr IS NOT NULL
)
SELECT e.empno
FROM emp e, no_null_mgr n
WHERE n.ok
  AND e.job = 'SALES'
  AND NOT EXISTS (
        SELECT 1 FROM mgr_set m WHERE m.mgr = e.empno
    );

